    for(int v:g[u]) if(!vis[v]) dfs1(v,g,vis,st);
    st.push(u);
}
void dfs2(int u, vector<vector<int>>& rg, vector<bool>& vis) {
    vis[u]=true; cout<<u<<" ";
    for(int v:rg[u]) if(!vis[v]) dfs2(v,rg,vis);
}
void kosaraju(int n, vector<vector<int>>& g, vector<vector<int>>& rg) {
    vector<bool> vis(n,false); stack<int> st;
    for(int i=0;i<n;i++) if(!vis[i]) dfs1(i,g,vis,st);
    fill(vis.begin(),vis.end(),false);
    while(!st.empty()){
        int u=st.top(); st.pop();
        if(!vis[u]){ dfs2(u,rg,vis); cout<<"\n"; }
    }
}
